import java.util.*;
import java.io.*;

public class Main {
    static final long MOD1 = 1000000007L;
    static final long MOD2 = 998244353L;
    static final int MAX_LEVEL = 7;
    static final long BASE_VAL = 1000000L;

    static long max_n;
    static long order_counter;
    static int result;
    static int[] prefix_sum = new int[MAX_LEVEL];
    static List<Integer>[] digit_list = new ArrayList[MAX_LEVEL];

    public static void build_sequences(long start_value, int level) {
        order_counter++;
        int val = (int)(((order_counter - start_value) % MOD2 + MOD2) % MOD2);
        digit_list[level].add(val);
        prefix_sum[level] = (int)((prefix_sum[level] + val) % MOD1);
        if (level == 6) return;
        for (int digit = 0; digit <= 9; digit++) {
            build_sequences(start_value * 10 + digit, level + 1);
        }
    }

    public static void traverse(long x) {
        if (x > max_n) return;
        if (x * BASE_VAL + BASE_VAL - 1 <= max_n && x * BASE_VAL * 10 > max_n) {
            long saved_order = order_counter;
            for (int depth = 0, factor = 1; depth <= 6; depth++, factor *= 10) {
                int size = digit_list[depth].size();
                int diff = (int)(((saved_order - x * factor) % MOD2 + MOD2) % MOD2);
                int target = (int)((MOD2 - diff) + 0);
                int pos = lowerBound(digit_list[depth], target);
                result = (int)((result + 1L * diff * size + prefix_sum[depth]) % MOD1);
                int sub = (int)((1L * MOD2 * (size - pos)) % MOD1);
                result = (result - sub + (int)MOD1) % (int)MOD1;
                order_counter += size;
            }
            return;
        }
        order_counter++;
        int diff = (int)(((order_counter - x) % MOD2 + MOD2) % MOD2);
        result = (int)((result + diff) % MOD1);
        for (int digit = 0; digit <= 9; digit++) {
            traverse(x * 10 + digit);
        }
    }

    public static int lowerBound(List<Integer> list, int target) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= target) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        max_n = Long.parseLong(br.readLine().trim());
        order_counter = 0;
        for (int i = 0; i < MAX_LEVEL; i++) {
            digit_list[i] = new ArrayList<>();
            prefix_sum[i] = 0;
        }
        build_sequences(0, 0);
        for (int i = 0; i <= 6; i++) {
            Collections.sort(digit_list[i]);
        }
        order_counter = 0;
        result = 0;
        for (int i = 1; i <= 9; i++) {
            traverse(i);
        }
        System.out.println(result);
    }
}
